examples:
核心逻辑可表示为：
```cpp
void doHire(Database& db) {
    std::string firstName;
    std::string lastName;
    std::cin >> firstName;
    std::cin >> lastName;
    auto& employee{db.addEmployee(firstName, lastName)};
    std::cout << std::format(
        "Hired employee {} {} with employee number {}.",
        firstName, lastName, employee.getEmployeeNumber())
        << std::endl;
}
```
